import type {
  HostingApi,
  HostingBundleView,
  HostingEvent,
  HostingHostKeyView,
  HostingInstallRequest,
  HostingPreflightRequest,
  HostingPreflightView,
  HostingProbeRequest,
  HostingSavedCredentials,
} from "@/features/hosting/types";

import { commands, events } from "./bindings";

// Tauri adapter of `rostalk-server-setup` (P13, ADR 0026). Like
// `core/tauri/adapter.ts` for the client, it is the only module of this entry
// point that talks to the shell; the bindings are generated by `make gen-ipc`
// from client/src-tauri/apps/server-setup.
export const tauriHostingApi: HostingApi = {
  async hostingPickKey(): Promise<string | null> {
    return commands.hostingPickKey();
  },

  async hostingProbe(
    request: HostingProbeRequest,
  ): Promise<HostingHostKeyView> {
    const reply = await commands.hostingProbe(request);
    return {
      ...reply,
      status: reply.status as HostingHostKeyView["status"],
    };
  },

  async hostingPreflight(
    request: HostingPreflightRequest,
  ): Promise<HostingPreflightView> {
    const reply = await commands.hostingPreflight(request);
    return {
      ...reply,
      firewall: reply.firewall as HostingPreflightView["firewall"],
    };
  },

  async hostingBundleStatus(): Promise<HostingBundleView> {
    return commands.hostingBundleStatus();
  },

  async hostingInstallStart(request: HostingInstallRequest): Promise<string> {
    return commands.hostingInstallStart(request);
  },

  async hostingCancel(operationId: string): Promise<boolean> {
    return commands.hostingCancel(operationId);
  },

  async hostingLoadCredentials(
    host: string,
    username: string,
  ): Promise<HostingSavedCredentials> {
    return commands.hostingLoadCredentials(host, username);
  },

  async hostingForgetCredentials(host: string, username: string): Promise<void> {
    await commands.hostingForgetCredentials(host, username);
  },

  subscribeHosting(listener: (event: HostingEvent) => void): () => void {
    let unlisten: (() => void) | undefined;
    let disposed = false;
    void events.hostingEventMessage
      .listen((event) => {
        listener(event.payload as unknown as HostingEvent);
      })
      .then((stop) => {
        if (disposed) {
          stop();
        } else {
          unlisten = stop;
        }
      });
    return () => {
      disposed = true;
      unlisten?.();
    };
  },
};
